import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def scope_nodes(doc, scope_title):
    node = node_by_title(doc, scope_title)
    if not node:
        return []
    return children(doc, node)

def table_rows(node):
    if not node or node.get("kind") != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(rows)]

def entities(doc, scope) -> list:
    ents = []
    ent_ids = set()

    # Find the scope's child nodes
    nodes = scope_nodes(doc, scope)

    # Machines
    m_node = next((n for n in nodes if n["title"] == f"{scope}: Machines"), None)
    if m_node:
        for idx, row in table_rows(m_node):
            mid = row["machine"]
            desc = f"Machine {mid}: CPU {row['CPU']}, memory {row['memory']}"
            ents.append({"id": mid, "description": desc})
            ent_ids.add(mid)

    # Tasks and Jobs
    t_node = next((n for n in nodes if n["title"] == f"{scope}: Task log"), None)
    if t_node:
        for idx, row in table_rows(t_node):
            tid = row["task"]
            jid = row["job"]
            if tid not in ent_ids:
                desc = f"Task {tid}: Job {jid}, priority {row['priority']}, CPU {row['CPU']}, memory {row['memory']}, run time {row['run time']}"
                ents.append({"id": tid, "description": desc})
                ent_ids.add(tid)
            if jid not in ent_ids:
                ents.append({"id": jid, "description": f"Job {jid}"})
                ent_ids.add(jid)

    return ents

def recorded_end(doc, scope) -> float or None:
    # All windows cover 0 to 1200.
    return 1200.0

def inputs(doc, scope) -> list:
    inputs_list = []
    nodes = scope_nodes(doc, scope)

    # Machine specs
    m_node = next((n for n in nodes if n["title"] == f"{scope}: Machines"), None)
    if m_node:
        for idx, row in table_rows(m_node):
            mid = row["machine"]
            fail_at = row["fails at"]
            return_at = row["returns at"]
            inputs_list.append({
                "id": f"input_m_{mid}",
                "time": 0.0,
                "kind": "machine_spec",
                "entities": [mid],
                "fields": {
                    "cpu": int(row["CPU"]),
                    "memory": int(row["memory"]),
                    "fails_at": int(fail_at) if fail_at != "-" else None,
                    "returns_at": int(return_at) if return_at != "-" else None
                },
                "src": [m_node["node_id"], idx]
            })

    # Task submissions
    t_node = next((n for n in nodes if n["title"] == f"{scope}: Task log"), None)
    if t_node:
        for idx, row in table_rows(t_node):
            if row["event"] == "submit":
                tid = row["task"]
                inputs_list.append({
                    "id": f"input_t_{tid}",
                    "time": float(row["time"]),
                    "kind": "task_submission",
                    "entities": [tid, row["job"]],
                    "fields": {
                        "job": row["job"],
                        "priority": int(row["priority"]),
                        "cpu": int(row["CPU"]),
                        "memory": int(row["memory"]),
                        "run_time": int(row["run time"])
                    },
                    "src": [t_node["node_id"], idx]
                })

    return inputs_list

def outcomes(doc, scope) -> list:
    outcomes_list = []
    nodes = scope_nodes(doc, scope)

    # Task log events
    t_node = next((n for n in nodes if n["title"] == f"{scope}: Task log"), None)
    if t_node:
        for idx, row in table_rows(t_node):
            event = row["event"]
            if event in ("start", "finish", "evict", "fail"):
                tid = row["task"]
                mid = row["machine"]
                outcomes_list.append({
                    "time": float(row["time"]),
                    "kind": f"task_{event}",
                    "entities": [tid] + ([mid] if mid != "-" else []),
                    "value": None,
                    "src": [t_node["node_id"], idx]
                })

    # Longest waits from Events section
    e_node = next((n for n in nodes if n["title"] == f"{scope}: Events"), None)
    if e_node and e_node["kind"] == "list":
        for idx, line in enumerate(e_node["lines"]):
            if "longest wait" in line.lower():
                # Extract number using regex
                match = re.search(r"longest wait[s]?:\s*(\d+)", line, re.IGNORECASE)
                if match:
                    val = int(match.group(1))
                    # Identify task if mentioned
                    task_match = re.search(r"task (T\d+)", line)
                    t_id = [task_match.group(1)] if task_match else []
                    outcomes_list.append({
                        "time": 1200.0, # Results are usually at the end
                        "kind": "longest_wait",
                        "entities": t_id,
                        "value": val,
                        "src": [e_node["node_id"], idx]
                    })

    return outcomes_list

def params(doc, scope) -> dict:
    # constants from the general description
    return {
        "window_length": 1200,
        "num_machines": 8,
        "production_tier_min_priority": 9,
        "free_tier_max_priority": 1
    }

