    nodes = scope_nodes(doc, scope)

    # Task events from log
    t_node = next((n for n in nodes if "Task log" in n["title"]), None)
    if t_node:
        for idx, row in table_rows(t_node):
            event = row["event"]
            if event in ("start", "finish", "evict", "fail"):
                tid = row["task"]
                mid = row["machine"]
                outcomes_list.append({
                    "time": float(row["time"]),
                    "kind": f"task_{event}",
                    "entities": [tid] + ([mid] if mid != "-" else []),
                    "value": None,
                    "src": [t_node["node_id"], idx]
                })

    # Events list
    e_node = next((n for n in nodes if "Events" in n["title"]), None)
    if e_node and e_node["kind"] == "list":
        for idx, line in enumerate(e_node["lines"]):
            # Machine failures/returns
            if "machine" in line.lower() and ("failed" in line.lower() or "returned" in line.lower()):
                time_match = re.search(r"Time (\d+)", line)
                if time_match:
                    time = float(time_match.group(1))
                    m_match = re.search(r"machine (M\d+)", line)
                    mid = m_match.group(1) if m_match else None
                    kind = "machine_fail" if "failed" in line.lower() else "machine_return"
                    outcomes_list.append({
                        "time": time,
                        "kind": kind,
                        "entities": [mid] if mid else [],
                        "value": None,
                        "src": [e_node["node_id"], idx]
                    })
            # Evictions (already in log, but explicitly in events too)
            elif "evicted" in line.lower():
                time_match = re.search(r"Time (\d+)", line)
                if time_match:
                    time = float(time_match.group(1))
                    t_matches = re.findall(r"task (T\d+)", line)
                    outcomes_list.append({
                        "time": time,
                        "kind": "task_evict",
                        "entities": t_matches,
                        "value": None,
                        "src": [e_node["node_id"], idx]
                    })
            # Longest wait
            elif "longest wait" in line.lower():
                time = 1200.0
                val_match = re.search(r"longest wait[s]?:\s*(\d+)", line, re.IGNORECASE)
                if val_match:
                    val = int(val_match.group(1))
                    t_match = re.search(r"task (T\d+)", line)
                    tid = t_match.group(1) if t_match else None
                    outcomes_list.append({
                        "time": time,
                        "kind": "longest_wait",
                        "entities": [tid] if tid else [],
                        "value": val,
                        "src": [e_node["node_id"], idx]
                    })

    # Queue at window end
    q_run_node = next((n for n in nodes if "Queue at window end: Tasks running" in n["title"]), None)
    if q_run_node:
        for idx, row in table_rows(q_run_node):
            outcomes_list.append({
                "time": 1200.0,
                "kind": "state_running",
                "entities": [row["task"], row["machine"]],
                "value": to_int(row["remaining"]),
                "src": [q_run_node["node_id"], idx]
            })

    q_wait_node = next((n for n in nodes if "Queue at window end: Tasks waiting" in n["title"]), None)
    if q_wait_node:
        for idx, row in table_rows(q_wait_node):
            outcomes_list.append({
                "time": 1200.0,
                "kind": "state_waiting",
                "entities": [row["task"]],
                "value": None,
                "src": [q_wait_node["node_id"], idx]
            })

    return outcomes_list

